const report = JSON.parse(JSON.stringify(prev.report));
const set = (k, n, d, rationale) => { if (!(k in report)) throw new Error("unknown key " + k); report[k] = { numerator: n, denominator: d, rationale }; };
set("tech_debt_tracking", 1, 1, "scripts/check-todos.sh enforces TODO(#issue) or TODO(B-nnn) in source files, in pre-commit and CI; BACKLOG.md tracks B-001..B-016 with reasons, earliest milestone and done dates (B-001, B-004, B-011, B-012, B-013 closed 2026-10-22).");
