set("automated_pr_review", 0, 1, "PRs #1-#3 have 0 review comments from automation; code scanning posts status checks and annotations, not a generated review.");
set("fast_ci_feedback", 1, 1, "gate on PR #3 (run 39781571328): created 12:49:41Z, completed 12:50:37Z (56 s); longest jobs fs-scan 22 s, sast 22 s, workflow-policy 19 s. Well under 10 minutes.");
set("deployment_frequency", 0, 1, "release.yml exists (tags on main, D-009) but no tag has been pushed; zero releases. The gate never deploys by design.");
set("release_notes_automation", 1, 1, ".github/release.yml groups generated notes by repository labels (type:feature, type:bug/fix-cycle, type:security, type:decision, area:deps); release.yml runs gh release create --generate-notes (D-009). Not yet exercised by a tag.");
set("release_automation", 1, 1, ".github/workflows/release.yml on v* tags: verifies the tag is semver and an ancestor of main, builds the macOS bundle via the reusable bundle.yml (provenance + cosign), creates the GitHub release with assets. actionlint clean; not yet exercised by a tag.");
set("documentation_freshness", 1, 1, "README.md, AGENTS.md, BACKLOG.md, docs/runbooks/, docs/decisions/D-009 all modified 2026-10-22 (PR #3).");
set("devcontainer", 1, 1, ".devcontainer/devcontainer.json: mcr.microsoft.com/devcontainers/rust:1-1-bookworm pinned by digest, node and github-cli features; post-create.sh installs actionlint 1.7.12, lychee 0.24.2, gitleaks 8.30.1, cargo-deny 0.20.2, markdownlint-cli2 0.24.0 and the Debian Tauri 2 libraries, then make hooks and make doctor.");
set("devcontainer_runnable", 0, 1, "Container not built in this session (no Docker available). post-create.sh passes sh -n and asset names were checked against each release; a successful build is unverified.");
set("runbooks_documented", 1, 1, "docs/runbooks/: README index plus red-gate, fix-cycle, stalled-mission, hooks-disabled, release. Each gives symptom, confirmation commands, fix table and the stop-and-involve-human conditions; app-dependent steps name the milestone that delivers them.");
set("automated_security_review", 1, 1, "GitHub code scanning default setup state=configured (languages: actions); gate.yml uploads Semgrep and Trivy SARIF via github/codeql-action/upload-sarif. PR #3 shows CodeQL, Semgrep OSS and Trivy as code-scanning checks; code-scanning/analyses lists all three tools.");
set("dependency_update_automation", 1, 1, "renovate.json validated with renovate@44 (grouped Cargo, pinned action digests, 7-day release age, weekly schedule, regex managers for rust-toolchain.toml, workflow images and devcontainer tool versions). Owner reports the Renovate GitHub App installed on 2026-10-22; first scheduled run (Monday before 06:00 Europe/Madrid) has not happened yet, so no Dependency Dashboard issue is visible.");
set("issue_labeling_system", 1, 1, "29 labels (gh label list): type:* (bug, feature, chore, decision, security), priority:P0-P3, area:* (core, ingest, metrics, ui, gate, ci, docs, deps), needs-triage, fix-cycle, plus GitHub defaults.");
set("backlog_health", 0, 1, "No GitHub issues exist; the backlog lives in BACKLOG.md by design (16 items, each with reason, earliest milestone, done dates). Nothing to evaluate against the issue-based criterion.");
set("code_quality_metrics", 0, 1, "Code scanning is enabled and receives Semgrep/Trivy/CodeQL results, but no code quality metric (coverage, duplication, complexity trend) is collected; coverage is B-005.");
set("flaky_test_detection", 0, 1, "No retry configuration or flaky tracking; PR #3 shows no duplicate check names.");
set("branch_protection", 1, 1, "Ruleset main-gate (id 25636994) active on refs/heads/main: pull_request (0 approvals, require_extra_approval_for_unattributed_changes=false), required_status_checks gate strict, non_fast_forward, deletion; no bypass actors. Verified via API 2026-10-22.");
set("service_flow_documented", 1, 1, "PRD v0.4 §11 data sources (attach primary, replay, host) and component diagram; README repository layout and gate; D-003 CI flow; D-004 telemetry flow; D-009 release flow; docs/runbooks/.");

const rows = Object.values(report);
const evaluated = rows.filter(r => r.numerator !== null);
const pass = evaluated.filter(r => r.numerator === r.denominator).length;
const skipped = rows.length - evaluated.length;
const pct = (100 * pass / evaluated.length).toFixed(1);
const uuid = (await tools.Execute({ summary: "uuid", command: "uuidgen | tr A-Z a-z", riskLevel: "low" })).output.trim();
const out = {
  repoUrl: prev.repoUrl, report,
  apps: { ".": { description: "droid-observatory: planned Tauri 2 + Leptos (Rust) desktop app observing Factory Missions across nine lanes; repository scaffold complete (CI gate with code scanning, release workflow, devcontainer, runbooks, hooks, config contract, docs), application code to be built by the mission" } },
  commitHash: "467e5d282e5b8751224448e85b4ef63f57ab9965", branch: "main", hasLocalChanges: false, hasNonRemoteCommits: false,
  droidVersion: "0.247.0", reportId: uuid, createdAt: Date.now(), sourceSessionId: prev.sourceSessionId,
};
const json = JSON.stringify(out, null, 2) + "\n";
await tools.Create({ file_path: p + ".factory/readiness-report.json", content: json });
await tools.Create({ file_path: p + "reports/readiness/2026-10-22-actions.json", content: json });
text(`total ${rows.length}; evaluated ${evaluated.length}; pass ${pass} (${pct}%); skipped ${skipped}`);
const changed = Object.keys(report).filter(k => JSON.stringify(report[k].numerator) !== JSON.stringify(prev.report[k].numerator));
text("changed outcomes: " + changed.map(k => `${k} ${prev.report[k].numerator}→${report[k].numerator}`).join(", "));
text("failing: " + evaluated.filter(r => r.numerator !== r.denominator).length + " = " + Object.keys(report).filter(k => report[k].numerator === 0).join(", "));

