const root="/Users/dct/code/EllyaOrg/projects/dalimaray/droid-observatory/";
const queries=[
  ["BACKLOG.md",1,100],["config/observatory.example.toml",1,110],["Makefile",1,145],
  ["ai/session/2026-10-22-session.md",425,100],[".factory/settings.json",1,80],
  ["docs/decisions/D-010-telemetry-contract.md",1,100],["README.md",58,70]
];
const r=await Promise.allSettled(queries.map(([p,o,l])=>tools.Read({file_path:root+p,offset:o,limit:l,line_numbers:true})));
r.forEach((x,i)=>text(`## ${queries[i][0]}\n${x.status==="fulfilled"?x.value:String(x.reason)}`));

