const r=await Promise.allSettled([
 tools.TodoWrite({todos:"1. [in_progress] Verify Factory model-switch behavior and inspect the five requested model references\n2. [pending] Correct the Fable ID in settings, README, D-006, config, and price table; log the interaction\n3. [pending] Validate the corrected files and determine how to restart this orchestrator on claude-fable-5.1\n4. [pending] Resume only pre-approval SPEC drafting, then stop for explicit approval"}),
 tools.Read({file_path:"/Users/dct/code/EllyaOrg/projects/dalimaray/droid-observatory/docs/decisions/D-006-models-per-role.md"}),
 tools.Read({file_path:"/Users/dct/code/EllyaOrg/projects/dalimaray/droid-observatory/config/prices/2026-10-22.toml"}),
 tools.FetchUrl({url:"https://docs.factory.ai/llms.txt"}),
 tools.Execute({summary:"Check branch before model corrections",command:"git -C /Users/dct/code/EllyaOrg/projects/dalimaray/droid-observatory status --short --branch",riskLevel:"low"})
]);
r.forEach((x,i)=>{const v=x.status==="fulfilled"?x.value:String(x.reason);text(`## ${["todo","D-006","price table","Factory documentation","status"][i]}\n${i===3&&typeof v==="object"?JSON.stringify(v).slice(0,25000):v}`)});

const urls=[
"https://docs.factory.com/models.md",
"https://docs.factory.com/missions/reference.md",
"https://docs.factory.com/factory-app/settings.md",
"https://docs.factory.com/missions/running-app.md"
];
const r=await Promise.allSettled(urls.map(url=>tools.FetchUrl({url})));
r.forEach((x,i)=>{let v=x.status==="fulfilled"?x.value:String(x.reason);text(`## ${urls[i]}\n${typeof v==="object"?JSON.stringify({title:v.title,status:v.metadata?.statusCode,markdown:v.markdown?.slice(0,12500)}):v}`)});

const root="/Users/dct/code/EllyaOrg/projects/dalimaray/droid-observatory";
const cmds={
 ports:"lsof -i -P -n | grep LISTEN | awk '{print $1, $9}' | sort -u",
 hw:"sysctl -n hw.memsize hw.ncpu; vm_stat | head -5; uptime",
 tools:"for t in cargo rustup trunk cargo-tauri gh droid agent-browser docker node; do printf '%s: ' $t; command -v $t >/dev/null 2>&1 && ($t --version 2>/dev/null | head -1) || echo MISSING; done; rustup target list --installed; cargo --list | grep -E 'tauri|llvm-cov|machete|deny' || true",
 keychain:"security find-generic-password -s droid-observatory/otlp-headers >/dev/null 2>&1 && echo 'otlp-headers: present' || echo 'otlp-headers: MISSING'; security find-generic-password -s droid-observatory/github-token >/dev/null 2>&1 && echo 'github-token: present' || echo 'github-token: MISSING'; gh auth status 2>&1 | head -4",
 sessions:"ls ~/.factory/sessions | head; ls ~/.factory/sessions | wc -l",
 pr:"gh pr view 23 --json state,mergeable,statusCheckRollup --jq '{state,mergeable,checks:[.statusCheckRollup[]|{name,status,conclusion}]}'"
};
const r=await Promise.allSettled([
 tools.Skill({skill:"mission-planning"}),
 ...Object.entries(cmds).map(([k,c])=>tools.Execute({summary:`Planning check: ${k}`,command:`cd ${root} && ${c}`,riskLevel:"low",timeout:90}))
]);
const keys=["skill",...Object.keys(cmds)];
r.forEach((x,i)=>{ if(i===0){text(`## skill: ${x.status}`);return;} const v=x.status==="fulfilled"?x.value:String(x.reason); text(`## ${keys[i]} (exit ${v.exitCode})\n${(v.output||v).toString().slice(0,4000)}`)});

const r = await Promise.allSettled([
  tools.Skill({ skill: 'mission-planning' }),
  tools.Skill({ skill: 'define-mission-skills' }),
  tools.TodoWrite({ todos: `1. [completed] Merge PR #23 (SPEC.md v0.1) to main after gate; Entry 25 appended uncommitted
2. [completed] Dependency readiness check (toolchain, crates, Tauri/Leptos path, OTLP, GitHub, session schema)
3. [in_progress] Validation readiness check: agent-browser vs trunk serve :3141, Tauri dev path, resource cost classification
4. [pending] Present boundary summary to owner: readiness, blockers/options, mission plan mapping to SPEC §3, propose_mission vs owner-run command
5. [pending] On confirmation: propose_mission, then author architecture.md, validation-contract.md, validation-state.json, features.json, AGENTS.md, skills/, services.yaml, init.sh, library/
6. [pending] Session log Entry 26 for this interaction` }),
]);
r.forEach((x, i) => text(`## r${i}\n${x.status === 'fulfilled' ? (typeof x.value === 'string' ? x.value.slice(0, 200) + '…' : JSON.stringify(x.value)) : String(x.reason)}`));
const ports = await tools.Execute({ summary: 'Check port 3141 and load', command: 'lsof -nP -iTCP:3141 -sTCP:LISTEN; echo "exit=$?"; uptime; ls /tmp/obs-readiness/ 2>&1', riskLevel: 'low' });
text(ports);

const r = await Promise.allSettled([
  tools.Execute({ summary: 'Check keychain entry exists without printing', command: 'security find-generic-password -s droid-observatory -a github-token >/dev/null 2>&1; echo "svc/acct exit=$?"; security find-generic-password -s droid-observatory/github-token >/dev/null 2>&1; echo "svc-only exit=$?"; security find-generic-password -l droid-observatory/github-token >/dev/null 2>&1; echo "label exit=$?"', riskLevel: 'low' }),
  tools.Execute({ summary: 'List reports dir and readiness scratch', command: 'ls -R reports | head -40; echo ---; ls /tmp/obs-readiness/logs; echo ---; git -C /Users/dct/code/EllyaOrg/projects/dalimaray/droid-observatory branch -a | head', riskLevel: 'low' }),
  tools.Grep({ pattern: 'reports/(readiness|usage|waste|ci|reference)', path: '/Users/dct/code/EllyaOrg/projects/dalimaray/droid-observatory/SPEC.md', output_mode: 'content', line_numbers: true }),
  tools.Execute({ summary: 'Find dependency readiness raw report', command: 'ls -la /tmp/obs-readiness/*.md /tmp/obs-readiness/logs/*.md 2>/dev/null; grep -l "keyring" /tmp/obs-readiness/logs/* 2>/dev/null | head', riskLevel: 'low' }),
]);
r.forEach((x, i) => text(`## r${i}\n${x.status === 'fulfilled' ? (typeof x.value === 'string' ? x.value : JSON.stringify(x.value, null, 1)) : String(x.reason)}`));

